insert into public.residency_catalog (id, name, city, edital_url, fee, specialties, institutions, steps, exam_edition_id, published, updated_at)
values (md5('residency:hrpp_2027')::uuid, 'HRPP', 'Presidente Prudente', 'https://www.vunesp.com.br', 800,
  '[{"name":"Anestesiologia","vacancies":5,"cutoff":""},{"name":"Cirurgia Geral","vacancies":6,"cutoff":""},{"name":"Clínica Médica","vacancies":20,"cutoff":""},{"name":"Dermatologia","vacancies":2,"cutoff":""},{"name":"Ginecologia e Obstetrícia","vacancies":5,"cutoff":""},{"name":"Infectologia","vacancies":3,"cutoff":""},{"name":"Medicina de Família e Comunidade","vacancies":2,"cutoff":""},{"name":"Medicina Intensiva","vacancies":2,"cutoff":""},{"name":"Neurocirurgia","vacancies":2,"cutoff":""},{"name":"Oftalmologia","vacancies":4,"cutoff":""},{"name":"Ortopedia e Traumatologia","vacancies":6,"cutoff":""},{"name":"Otorrinolaringologia","vacancies":2,"cutoff":""},{"name":"Pediatria","vacancies":18,"cutoff":""},{"name":"Psiquiatria","vacancies":7,"cutoff":""},{"name":"Radiologia e Diagnóstico por Imagem","vacancies":2,"cutoff":""}]'::jsonb, '[]'::jsonb, '[{"id":"edital","key":"edital","label":"Edital publicado","type":"inscricao","date":"2026-09-22","end":null,"done":false},{"id":"reducao","key":"reducao","label":"Pedido de redução da taxa","type":"inscricao","date":"2026-10-07","end":"2026-10-08","done":false},{"id":"inscricao","key":"inscricao","label":"Inscrição","type":"inscricao","date":"2026-10-07","end":"2026-10-26","done":false},{"id":"boleto","key":"boleto","label":"Pagamento do boleto","type":"inscricao","date":"2026-10-26","end":null,"done":false},{"id":"x-resultado-da-reducao-da-taxa","key":"custom","label":"Resultado da redução da taxa","type":"inscricao","date":"2026-10-16","end":null,"done":false},{"id":"local","key":"local","label":"Local de prova divulgado","type":"prova","date":"2026-11-27","end":null,"done":false},{"id":"prova","key":"prova","label":"Prova","type":"prova","date":"2026-12-05","end":null,"done":false},{"id":"gabarito","key":"gabarito","label":"Gabarito","type":"prova","date":"2026-12-08","end":null,"done":false},{"id":"recurso","key":"recurso","label":"Prazo de recurso","type":"prova","date":"2026-12-10","end":null,"done":false},{"id":"resultado1","key":"resultado1","label":"Resultado da 1ª fase","type":"resultado","date":"2027-01-06","end":null,"done":false},{"id":"final","key":"final","label":"Resultado final","type":"resultado","date":"2027-02-16","end":null,"done":false},{"id":"x-matricula","key":"custom","label":"Matrícula","type":"resultado","date":"2027-02-17","end":null,"done":false}]'::jsonb, (select ed.id from exam_editions ed join exams e on e.id = ed.exam_id join institutions i on i.id = e.institution_id
      where i.abbreviation = 'UNOESTE/HRPP' and e.name = 'R1 Acesso Direto' and ed.year = 2027 limit 1), true, now())
on conflict (id) do update set name = excluded.name, city = excluded.city, edital_url = excluded.edital_url, fee = excluded.fee,
  specialties = excluded.specialties, institutions = excluded.institutions, steps = excluded.steps,
  exam_edition_id = excluded.exam_edition_id, published = true, updated_at = now();

